INSERT INTO `attestations` (`id`,`form_id`,`source_id`,`date_label`,`year`,`witness`,`locator`,`excerpt`,`confidence`,`witness_type`,`repository`,`shelfmark`,`facsimile_url`,`directly_inspected`,`editorial_note`) VALUES
(98,15,100,'1704',1704,'A banking-exchange passage in John Harris’s Lexicon technicum uses Salary for the banker’s compensation.','Image [187], banking-exchange passage; e-rara content image 2867251','which is the Salary of the Banker','established','printed_book','ETH-Bibliothek Zürich','Rar 98 Ex.A GF, content image 2867251','https://www.e-rara.ch/zut/content/zoom/2867251?query=SALARY',1,'The e-rara page image was directly inspected. It verifies a contextual 1704 use of Salary for a banker’s compensation; it is not a SALARY headword, is not claimed as the earliest English occurrence, and does not prove the Latin ancestry or the salt-payment myth.'),
(99,80,100,'1704',1704,'The PAPER-OFFICE entry in John Harris’s Lexicon technicum includes Letters of Intelligence among official papers communicated to the King’s Council.','Image [600], left column, PAPER-OFFICE entry; e-rara content image 2867664','Instructions for Foreign Ministers, Letters of Intelligence, and many other Publick Papers','established','printed_book','ETH-Bibliothek Zürich','Rar 98 Ex.A GF, content image 2867664','https://www.e-rara.ch/zut/content/zoom/2867664?query=INTELLIGENCE',1,'The e-rara page image was directly inspected. It verifies a contextual 1704 use of Intelligence for official information or reports; it is not an INTELLIGENCE headword, is not claimed as the earliest occurrence, and does not prove the mental-capacity sense or deeper ancestry.'),
(100,158,100,'1704',1704,'John Harris’s NOSOCOMIUM entry uses Hospital for an institution where poor sick people are attended and, if possible, cured.','Image [572], left column, entry NOSOCOMIUM; e-rara content image 2867636','NOSOCOMIUM, is an Hospital for Poor Sick People; where they are attended, and cured, if possible.','established','printed_book','ETH-Bibliothek Zürich','Rar 98 Ex.A GF, content image 2867636','https://www.e-rara.ch/zut/content/zoom/2867636?query=HOSPITAL',1,'The e-rara page image was directly inspected. It verifies a contextual 1704 use of Hospital in the medical-care sense; it is not a HOSPITAL headword, is not claimed as the earliest occurrence, and does not prove the earlier lodging senses or Latin ancestry.'),
(101,66,100,'1704',1704,'A passage in John Harris’s Lexicon technicum cites a Lecture by Nehemiah Grew about varieties of taste read before the Royal Society.','Image [818], left column, lower TAST passage; e-rara content image 2867882','Dr. Grew, in his Lecture about the Diversities of Tasts','established','printed_book','ETH-Bibliothek Zürich','Rar 98 Ex.A GF, content image 2867882','https://www.e-rara.ch/zut/content/zoom/2867882?query=LECTURE',1,'The e-rara page image was directly inspected. It verifies a contextual 1704 use of Lecture for a discourse read before the Royal Society; it is not a LECTURE headword, is not claimed as the earliest occurrence, and does not prove the Latin reading ancestry.');
